declare(strict_types=1);
function esc(mixed $s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function site_header(string $title,bool $owner=false):void {echo '<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.esc($title).' — НейроДело</title><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/brand-ui.css"><link rel="stylesheet" href="/publications.css"><link rel="stylesheet" href="/site.css?v=portfolio-only-20261109">'.($owner?'<meta name="robots" content="noindex,nofollow">':'').'</head><body data-site-mode="portfolio-only"><header class="header wrap"><a class="logo" href="/">✳︎ НейроДело<span class="logo-dot">.</span></a><nav aria-label="Навигация"><a href="/">Главная</a><a href="/portfolio.php">Портфолио</a></nav><a class="header-cta" href="/#contact">Написать →</a></header>';}
function site_footer():void {echo '<footer class="wrap footer"><a class="logo" href="/">НейроДело.</a><a href="/portfolio.php">Портфолио</a><span>© '.date('Y').' НейроДело</span><a href="/studio.php" class="owner-entry" aria-label="Кабинет владельца">◈</a></footer><script src="/site.js" defer></script></body></html>';}
function site_card(array $item):void {$b=$item['body'];echo '<a class="publication-card" href="/portfolio-case.php?case='.esc($item['slug']).'">';if(!empty($b['cover']['id']))echo '<img loading="lazy" src="/portfolio-api.php?r=media&amp;id='.(int)$b['cover']['id'].'" alt="'.esc($b['cover']['caption']??$b['title']).'">';echo '<h2>'.esc($b['title']).'</h2><p>'.esc($b['short_description']??mb_substr($b['text']??'',0,200)).'</p></a>';}
